mapper.select:
SELECT `id` as id, `name` as name FROM `ut_type_of_systems` WHERE `is_active` = 1 AND name LIKE CONCAT("%", #{filter.searchText}, "%")
AND id = #{filter.id}
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `term_conditions` WHERE `is_active` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
AND term_condition_type_id = #{filter.termConditionTypeId}
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `crm_activities_status` WHERE `is_active` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `term_condition_types` WHERE `is_active` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `contact_name` as name, `is_apply` as isApply FROM `customer_contacts` WHERE `is_active` = 1
AND customer_id = #{filter.organizationId}
AND `contact_name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT customer_contacts.id AS id, customer_contacts.contact_name AS name, customer_contacts.is_apply AS isApply FROM customer_contacts WHERE customer_contacts.is_active = 3 AND customer_contacts.contact_type = 2 AND customer_id IS NULL
AND ( customer_contacts.contact_name LIKE CONCAT("%", #{filter.searchText}, "%") OR customer_contacts.contact_telephone LIKE CONCAT("%", #{filter.searchText}, "%") OR customer_contacts.contact_email LIKE CONCAT("%", #{filter.searchText}, "%") )
ORDER BY customer_contacts.id DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, name AS name FROM egroups WHERE 1 = 1
AND name LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY name ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, name AS name FROM type_network_partner_managements WHERE is_active = 1
AND name LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY name ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, name AS name FROM partner_management_positions WHERE 1 = 1
AND name LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY name ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, name AS name FROM partner_management_industries WHERE 1 = 1
AND name LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY name ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT class_partner_managements.id AS id, class_partner_managements.name AS name FROM class_partner_managements INNER JOIN class_egroup_partner_managements cepm ON cepm.class_id = class_partner_managements.id INNER JOIN employee_egroups ee ON ee.egroup_id = cepm.egroup_id INNER JOIN employees current_employee ON current_employee.id = ee.employee_id AND current_employee.is_active = 1 AND current_employee.user_id = #{userId} WHERE class_partner_managements.is_active = 1
AND class_partner_managements.name LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY class_partner_managements.id DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT crm_support_pipeline_settings.id AS id, crm_support_pipeline_settings.description AS name FROM crm_support_pipeline_settings WHERE crm_support_pipeline_settings.is_active = 1
AND crm_support_pipeline_settings.description LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY crm_support_pipeline_settings.id DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `cgroups` WHERE `is_active` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT cgroups.id AS id, cgroups.name AS name FROM cgroups WHERE cgroups.is_active = 3 AND cgroups.group_type = 2 AND cgroups.id IN ( SELECT cgroup_id FROM cgroup_companies WHERE company_id IN ( SELECT company_id FROM user_companies WHERE user_id = #{userId} ) )
AND cgroups.id IN ( SELECT cgroup_id FROM cgroup_companies WHERE company_id = #{filter.companyId} )
AND cgroups.name LIKE CONCAT("%", #{filter.searchText}, "%")
AND cgroups.created_by = #{userId}
GROUP BY cgroups.id, cgroups.name ORDER BY cgroups.name ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `customer_zones` WHERE `is_active` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY `name` ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `customer_markets` WHERE `is_active` = 1
AND `zone_id` = #{filter.zoneId}
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY `name` ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT boms.id AS id, boms.date AS `date`, boms.code AS code, boms.note AS note FROM boms WHERE boms.status = 1 AND boms.is_approve = 1
AND code LIKE CONCAT("%", #{filter.searchText}, "%")
AND boms.company_id = #{filter.companyId}
ORDER BY date DESC, code ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id as id, name as name, number as number, symbol as symbol, color as color, is_main_total as isMainTotal, is_vendor as showVendor FROM `project_costing_terms` WHERE `is_active` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT
id as id,
quotation_code as code,
total_amount as amount
FROM `quotations`
WHERE status = 1 AND is_close = 0

    AND `quotation_code` LIKE CONCAT("%", #{filter.searchText}, "%")


    AND type = #{filter.type}


    AND company_id = #{filter.companyId}


    AND customer_id = #{filter.organizationId}

ORDER BY id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT q.id AS id, CONCAT(q.quotation_code, ' (', FORMAT((q.total_amount - IFNULL(q.discount, 0) + IFNULL(q.total_vat, 0)), 2), ' $)') AS label, ROUND((q.total_amount - IFNULL(q.discount, 0) + IFNULL(q.total_vat, 0)), 2) AS amount FROM quotations AS q LEFT JOIN customers ON customers.id = q.customer_id AND customers.is_active = 1 LEFT JOIN customer_contacts ON customer_contacts.id = q.customer_contact_id WHERE q.status > 0 AND q.company_id IN ( SELECT company_id FROM user_companies WHERE user_id = #{userId} )
AND q.quotation_code LIKE CONCAT("%", #{filter.searchText}, "%")
AND q.company_id = #{filter.companyId}
AND q.customer_id = #{filter.organizationId}
ORDER BY q.id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT orders.id AS id, CONCAT(orders.order_code, ' (', FORMAT(orders.total_amount, 3), ' $)') AS label FROM orders LEFT JOIN customers ON customers.id = orders.customer_id LEFT JOIN customer_contacts ON customer_contacts.id = orders.customer_contact_id WHERE orders.is_approve = 1 AND orders.status > 0 AND orders.company_id IN ( SELECT company_id FROM user_companies WHERE user_id = #{userId} )
AND orders.order_code LIKE CONCAT("%", #{filter.searchText}, "%")
AND orders.company_id = #{filter.companyId}
AND orders.customer_id = #{filter.organizationId}
ORDER BY orders.id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id as id, quotation_code as code, total_amount as amount FROM `quotations` WHERE status > 0
AND customer_id = #{filter.organizationId}
AND 1 = 0
AND `quotation_code` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `to_code` as name FROM `transfer_orders` WHERE `status` > 0
AND `transfer_code` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT sales_orders.`id` as id, sales_orders.`so_code` as code, sales_orders.`order_date` as `date`, CONCAT_WS(' - ', customers.customer_code, CONCAT(customers.name_kh, '(', customers.name, ')')) as organizationName, sales_orders.total_amount + IFNULL(sales_orders.total_vat,0) - IFNULL(sales_orders.discount,0) - IFNULL(sales_orders.total_deposit,0) AS totalAmount, sales_orders.balance as balance, sales_orders.status as status FROM `sales_orders` INNER JOIN customers ON customers.id = sales_orders.customer_id WHERE `status` IN (1,2)
AND sales_orders.ar_id = #{filter.chartAccountId}
AND sales_orders.company_id = #{filter.companyId} AND sales_orders.balance > 0
AND sales_orders.type = #{filter.type}
AND sales_orders.customer_id = #{filter.organizationId}
AND sales_orders.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})
AND sales_orders.is_deposit = 1 AND sales_orders.is_close_deposit = 0 AND sales_orders.order_id = #{filter.saleOrderId}
AND sales_orders.id NOT IN (SELECT sales_order_id FROM credit_memos WHERE status > 0)
AND sales_orders.`so_code` LIKE CONCAT("%", #{filter.searchText}, "%")
GROUP BY sales_orders.id ORDER BY sales_orders.id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `reasons` WHERE `is_active` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

