SELECT cos.id AS id, cos.name AS name, cos.is_apply AS isApply FROM crm_opportunity_stags AS cos WHERE cos.is_active = 1
AND cos.name LIKE CONCAT("%", #{filter.searchText}, "%")
GROUP BY cos.id, cos.name, cos.is_apply LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT cpss.crm_opportunity_stag_id AS id, cpss.percent AS percent FROM crm_opportunity_stags AS cos
INNER JOIN crm_pipeline_setting_stags AS cpss ON cpss.crm_opportunity_stag_id = cos.id WHERE cos.is_active = 1 AND cpss.crm_opportunity_stag_id = #{filter.stageId} AND cpss.crm_pipeline_setting_id = #{filter.pipelineId}
AND cos.name LIKE CONCAT("%", #{filter.searchText}, "%")
GROUP BY cos.id, cos.name, cos.is_apply ORDER BY IFNULL(MIN(cpss.ordering), cos.id) ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, name AS name, type AS typeId FROM crm_opportunity_sources WHERE is_active = 1
