SELECT DISTINCT coa.id AS id, coa.name AS name FROM crm_opportunity_activities AS coa LEFT JOIN crm_opportunity_stag_activities AS cosa ON cosa.crm_opportunity_activity_id = coa.id WHERE coa.is_active = 1
AND coa.name LIKE CONCAT("%", #{filter.searchText}, "%")
AND cosa.crm_opportunity_stag_id = #{filter.stageId}
ORDER BY coa.name ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT DISTINCT csa.id AS id, csa.name AS name FROM crm_support_activities AS csa LEFT JOIN crm_support_stag_activities AS cssa ON cssa.crm_support_activity_id = csa.id WHERE csa.is_active = 1
AND csa.name LIKE CONCAT("%", #{filter.searchText}, "%")
AND cssa.crm_support_stag_id = #{filter.stageId}
ORDER BY csa.name ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

